"""任务注册表 — 收集所有可用任务，支持特性开关。"""from __future__ import annotationsimport osfrom typing import Dict, List, Optionalfrom .task import (    Task,    TaskType,    LocalBashTask,    LocalAgentTask,    RemoteAgentTask,    InProcessTeammateTask,    LocalWorkflowTask,    MonitorMCPTask,    DreamTask,)class FeatureFlags:    """从环境变量读取特性开关。"""    def __init__(self):        self._flags: Dict[str, bool] = {}        self._load_defaults()    def _load_defaults(self) -> None:        defaults = {            "WORKFLOW_SCRIPTS": True,            "MONITOR_TOOL": False,            "DREAM_MODE": False,            "REMOTE_AGENT": False,        }        for key, default in defaults.items():            env_val = os.getenv(f"AICLIP_{key}", "").lower()            if env_val in ("1", "true", "yes"):                self._flags[key] = True            elif env_val in ("0", "false", "no"):                self._flags[key] = False            else:                self._flags[key] = default    def is_enabled(self, flag: str) -> bool:        return self._flags.get(flag, False)    def set_flag(self, flag: str, enabled: bool) -> None:        self._flags[flag] = enabledclass TaskRegistry:    """任务注册表 — 管理所有 Task 实现的单例注册中心。"""    def __init__(self, feature_flags: Optional[FeatureFlags] = None):        self._tasks: Dict[TaskType, Task] = {}        self._features = feature_flags or FeatureFlags()        self._register_builtin()    def _register_builtin(self) -> None:        """注册内置任务，根据特性开关过滤。"""        # 始终可用        self.register(LocalBashTask())        self.register(LocalAgentTask())        self.register(InProcessTeammateTask())        # 按特性开关        if self._features.is_enabled("WORKFLOW_SCRIPTS"):            self.register(LocalWorkflowTask())        if self._features.is_enabled("MONITOR_TOOL"):            self.register(MonitorMCPTask())        if self._features.is_enabled("DREAM_MODE"):            self.register(DreamTask())        if self._features.is_enabled("REMOTE_AGENT"):            self.register(RemoteAgentTask())    def register(self, task: Task) -> None:        self._tasks[task.task_type] = task    def unregister(self, task_type: TaskType) -> None:        self._tasks.pop(task_type, None)    def get_task_by_type(self, task_type: TaskType) -> Optional[Task]:        return self._tasks.get(task_type)    def get_all_tasks(self) -> List[Task]:        return list(self._tasks.values())    def get_available_types(self) -> List[TaskType]:        return list(self._tasks.keys())    @property    def features(self) -> FeatureFlags:        return self._features